/**
 * Renders every fixture in fixtures/ into examples/<fixture>/ and writes examples/README.md.
 * Everything under examples/ is generated by this script and never edited by hand.
 *
 *   npm run examples
 */
import { mkdir, readdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { SUBMISSION_DIR } from "../src/paths.js";
import { loadDesignConfig, readContentFile, renderInsight, type RenderOutcome } from "../src/pipeline.js";
import { ChromiumRenderer } from "../src/renderer.js";

const FIXTURES = path.join(SUBMISSION_DIR, "fixtures");
const EXAMPLES = path.join(SUBMISSION_DIR, "examples");

/** What each fixture is meant to show, in the order the summary lists them. */
const PURPOSE: Record<string, string> = {
  normal: "Normal approved content renders and passes.",
  "special-characters": "Quotes, ampersands, currency, accents, a no-break space, `$&` and `{{body}}` survive byte for byte.",
  "html-script-input": "Script and HTML-like text is shown literally. Nothing executes and nothing is requested.",
  "long-title": "A title longer than three lines is reported as `TITLE_OVERFLOW`.",
  "long-body": "A body taller than its region is reported as `BODY_OVERFLOW`. It is not clipped.",
  "missing-title": "An empty title is a predictable `MISSING_REQUIRED_FIELD`. Nothing is rendered.",
  "missing-source-note": "An absent source note is a predictable `MISSING_REQUIRED_FIELD`. Nothing is rendered.",
  "changed-after-approval": "A body edited after approval (42 changed to 47) fails `APPROVAL_DIGEST_MISMATCH`. Nothing is rendered.",
  malformed: "Wrong types, unknown fields and a missing approval record fail `INPUT_INVALID`.",
};

const fixtures = (await readdir(FIXTURES)).filter((f) => f.endsWith(".json")).map((f) => path.basename(f, ".json"));
const ordered = [...Object.keys(PURPOSE).filter((n) => fixtures.includes(n)), ...fixtures.filter((n) => !(n in PURPOSE)).sort()];

await rm(EXAMPLES, { recursive: true, force: true });
await mkdir(EXAMPLES, { recursive: true });

const design = await loadDesignConfig();
const renderer = await ChromiumRenderer.launch();
const results: Array<{ name: string; outcome: RenderOutcome }> = [];
try {
  for (const name of ordered) {
    const outcome = await renderInsight(await readContentFile(path.join(FIXTURES, `${name}.json`)), {
      design,
      renderer,
      outDir: path.join(EXAMPLES, name),
    });
    results.push({ name, outcome });
    const codes = outcome.report.failures.map((f) => f.code).join(", ");
    console.log(`${name.padEnd(24)} ${outcome.report.status.toUpperCase()}${codes ? `  ${codes}` : ""}`);
  }
} finally {
  await renderer.close();
}

const rows = results.map(({ name, outcome: { report } }) => {
  const codes = [...new Set(report.failures.map((f) => `\`${f.code}\``))].join(", ") || "none";
  const links = [
    report.outputs.png ? `[${report.outputs.png}](${name}/${report.outputs.png})` : "no PNG",
    `[report.json](${name}/report.json)`,
    report.outputs.html ? `[insight.html](${name}/insight.html)` : null,
  ].filter(Boolean);
  return `| [\`${name}\`](../fixtures/${name}.json) | ${PURPOSE[name] ?? ""} | **${report.status}** | ${codes} | ${links.join(" · ")} |`;
});

await writeFile(
  path.join(EXAMPLES, "README.md"),
  `# Rendered examples

Generated by \`npm run examples\` from the fixtures in [\`../fixtures\`](../fixtures). Do not edit by hand.

A passing render writes \`insight.png\`. A render that fails visual validation keeps its
PNG as \`insight.failed.png\`, for diagnosis, so it can never be mistaken for a deliverable.
Content that is invalid, incomplete or changed since approval is not rendered at all.
Every case writes \`report.json\`.

| Fixture | What it shows | Status | Failure codes | Output |
| --- | --- | --- | --- | --- |
${rows.join("\n")}

Re-rendering on the same machine and Chromium build gives pixel-identical output, which
\`tests/render.test.ts\` checks. The committed PNGs were rendered on Windows. Font
anti-aliasing differs between operating systems, so PNG bytes rendered elsewhere can differ
even when layout and validation results are the same.
`,
);
// Machine-readable index of the same results, used by the static showcase (scripts/build-site.mjs).
const index = results.map(({ name, outcome: { report } }) => ({
  fixture: name,
  purpose: PURPOSE[name] ?? null,
  content_id: report.content_id,
  status: report.status,
  checks: report.checks,
  failure_codes: [...new Set(report.failures.map((f) => f.code))],
  png: report.outputs.png ? `${name}/${report.outputs.png}` : null,
  html: report.outputs.html ? `${name}/${report.outputs.html}` : null,
  report: `${name}/report.json`,
}));
await writeFile(path.join(EXAMPLES, "index.json"), `${JSON.stringify(index, null, 2)}\n`);

console.log(`\nWrote ${path.relative(process.cwd(), EXAMPLES)}${path.sep}README.md and index.json`);
